ACMsg.STM32_HT16K33SEGMENT14_HT16K33SEGMENT14_SET_CHARACTER = "Gibt ein einzelnes alphanumerisches Zeichen an der angegebenen Ziffer aus. Es sind nur Zeichen aus dem Zeichensatz der Klasse verfügbar; andere Zeichen können mit 'set_glyph()' definiert und dargestellt werden. Diese Methode aktualisiert den Anzeige-Puffer, sendet ihn aber nicht an das Display. Rufen Sie 'update()' auf, um den Puffer auf dem Display darzustellen. Argumente: char (string):  Das anzuzeigende Zeichen. digit (int):    Die Ziffer, an der das Zeichen angezeigt wird. Standard: 0 (linkeste Ziffer). Rückgabe: Die Instanz (self)";
ACMsg.STM32_HT16K33SEGMENT14_HT16K33SEGMENT14_SET_CODE = "Gibt ein einzelnes alphanumerisches Zeichen an der angegebenen Ziffer aus. Es sind nur Zeichen aus dem Zeichensatz der Klasse verfügbar; andere Zeichen können mit 'set_glyph()' definiert und dargestellt werden. Diese Methode aktualisiert den Anzeige-Puffer, sendet ihn aber nicht an das Display. Rufen Sie 'update()' auf, um den Puffer auf dem Display darzustellen. Argumente: code (int):     Der klassen­spezifische Code des Zeichens. digit (int):    Die Ziffer, an der das Zeichen angezeigt wird. Standard: 0 (linkeste Ziffer). Rückgabe: Die Instanz (self)";
ACMsg.STM32_HT16K33SEGMENT14_HT16K33SEGMENT14_SET_GLYPH = "Setzt die eingegebene Zeichenmatrix (ein 16-Bit-Integer) in die angegebene Reihe und fügt bei Bedarf einen Dezimalpunkt hinzu. Der Zeichenmatrixwert wird berechnet, indem die Bit(s) gesetzt werden, die die zu beleuchtenden Segmente repräsentieren: 0                           9 _ 5 |   | 1           8 \\ | / 10 |   |                        \\|/ 6  - -  7 4 |   | 2              /|              | _ |                   13 / | \\ 11          . 14 3                           12 Bit 14 ist der Punkt, wird aber mit Parameter 3 gesetzt. Hinweis: Bit 15 wird vom Display nicht gelesen Argumente: glyph (int):   Das Glyph-Muster. digit (int):   Die Ziffer, an der das Glyph angezeigt wird. Standard: 0 (linkeste Ziffer). Rückgabe: Die Instanz (self)";
ACMsg.STM32_HT16K33SEGMENT14_HT16K33SEGMENT14_SET_NUMBER = "Gibt einen einzelnen Dezimalwert (0-9) an der angegebenen Ziffer aus. Diese Methode aktualisiert den Anzeige-Puffer, sendet ihn aber nicht an das Display. Rufen Sie 'update()' auf, um den Puffer auf dem Display darzustellen. Argumente: number (int):  Die anzuzeigende Zahl. digit (int):   Die Ziffer, an der die Zahl angezeigt wird. Standard: 0 (linkeste Ziffer). Rückgabe: Die Instanz (self)";
ACMsg.STM32_HT16K33SEGMENT14_HT16K33SEGMENT14__SET_DIGIT = "Methode `_set_digit` von `HT16K33Segment14`.";
